 * figure it stays live. A clerk settling a claim whose due is above the sheet's clerk limit (a due of n/a is within any
 * limit) makes it PENDING instead, live and unfixed. A claim with no proofs whose due is above the sheet's proof threshold in
 * force on its date is refused settling or approving — before the clerk limit is considered, so it never goes PENDING.
 * A claim with an empty note whose due (as shown now) is above the sheet's note threshold in force on its date is refused opening. Only a steward approves a PENDING claim (fixing its due at its live
 * figure, plus any late charge, at that moment) — not the user who opened it — or rejects it, with a reason, back to OPEN.
 * Only a steward re-settles a SETTLED claim, fixing its due again at the figure it would have today as an open claim
 * bound by no statement (today's rates, grades, floor and late charge); its previous due is kept for the audit.
 * Only a steward voids a SETTLED claim, and only while the sheet's today is within 7 days of its settlement (the
 * status log's latest SETTLED date); it keeps its number and its frozen due, which leaves every total.
 */
public class ApplyClaimAction {

    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a SETTLED claim. */
    static final int VOID_SETTLED_DAYS = 7;

    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim,
            @Val ClaimActionRequest request, SheetRepository sheets,
            PersonRepository people, RateRepository rates, SettingRepository settings, PeriodRepository periods,
            ClaimRepository claims, ClaimLogRepository logs, Out<ClaimAction> applied, Out<ClaimNumber> number, Out<PreviousDue> previous, Out<Claim> updated) throws InvalidClaimException {
        ClaimAction found = ClaimAction.of(action);
        if (found == null) {
            throw new InvalidClaimException("No such claim action: " + action);
        }
        if (!found.allowedFrom(claim.status())) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
        }
        if ((found == ClaimAction.OPEN || found == ClaimAction.SETTLE || found == ClaimAction.VOID)
                && !settings.find(claim.sheetId()).may(user, action)) {
            throw new InvalidClaimException("The user's role is not allowed to " + action + " a claim.");
        }
        if (found == ClaimAction.SETTLE && claim.deferred(sheets.today(claim.sheetId()))) {
            throw new InvalidClaimException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
        }
        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
        }
        if (found == ClaimAction.APPROVE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot approve it.");
        }
        if ((found == ClaimAction.APPROVE || found == ClaimAction.REJECT)
                && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can " + action + " a pending claim.");
        }
        if (found == ClaimAction.RESETTLE && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can re-settle a settled claim.");
        }
        if (found == ClaimAction.VOID && claim.status() == ClaimStatus.SETTLED) {
            if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
                throw new InvalidClaimException("Only a steward can void a settled claim.");
            }
            LocalDate settledOn = logs.find(claim.sheetId(), claim.id()).stream()
                    .filter((l) -> l.status() == ClaimStatus.SETTLED).map(ClaimLogLine::date)
                    .reduce((a, b) -> b).orElse(null);
            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimException("A settled claim can be voided only within " + VOID_SETTLED_DAYS
                        + " days of its settlement.");
            }
        }
        if (found == ClaimAction.REJECT && request.reason().isEmpty()) {
            throw new InvalidClaimException("A reason is required to reject a claim.");
        }
        BigDecimal due = found.settles() ? settledDue(found == ClaimAction.RESETTLE ? claim.asOpenUnbound() : claim, sheets, people, rates, settings, claims) : claim.due();
        if (found == ClaimAction.OPEN && (claim.note() == null || claim.note().isBlank())
                && settings.dated(claim.sheetId()).needsNote(claim.date(),
                        ClaimDueNow.of(claim, sheets, people, rates, settings, claims))) {
            throw new InvalidClaimException("The claim's due is above the note threshold: it needs a note to be opened.");
        }
        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE) && claim.proofs() == 0
                && settings.dated(claim.sheetId()).needsProof(claim.date(), due)) {
            throw new InvalidClaimException("The claim's due is above the proof threshold: it needs a proof to be "
                    + (found == ClaimAction.SETTLE ? "settled" : "approved") + ".");
        }
        if (found == ClaimAction.SETTLE && !settings.find(claim.sheetId()).maySettle(user, due)) {
            found = ClaimAction.PEND;
            due = null;
        }
        String next = switch (found) {
            case OPEN -> nextNumber(claim, sheets, settings, periods);
            default -> claim.number();
        };
        applied.set(found);
        previous.set(new PreviousDue(claim.due(), claim.status() == ClaimStatus.SETTLED));
        number.set(new ClaimNumber(next));
        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
    }

    /** The number opening the claim gives it now: the sheet's next, or the next within its period under period numbering. */
    static String nextNumber(Claim claim, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods) {
        LocalDate from = settings.periodNumberingFrom(claim.sheetId());
        if (from == null || sheets.today(claim.sheetId()).isBefore(from)) {
            return String.valueOf(sheets.nextClaimNumber(claim.sheetId()));
        }
        Period period = periods.findAll(claim.sheetId()).stream().filter((p) -> p.contains(claim.dueBy())).findFirst()
                .orElse(null);
        String prefix = period == null ? "X" : period.name();
        String key = period == null ? "" : period.name().toLowerCase();
        return prefix + "-" + sheets.nextPeriodClaimNumber(claim.sheetId(), key);
    }

    private static BigDecimal settledDue(Claim claim, SheetRepository sheets, PersonRepository people,
            RateRepository rates, SettingRepository settings, ClaimRepository claims) {
        return ClaimDueNow.of(claim, sheets, people, rates, settings, claims);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Records the claim's status change, with its person's name; runs only once the change has been allowed.
 * Settling and approving also record the due fixed (n/a when the grade had no rate); rejecting records its reason;
 * re-settling records the previous due and the new one; voiding a SETTLED claim records the frozen due it reverses.
 */
public class AuditClaimAction {
    public void audit(@Val ClaimAction action, @Val ClaimNumber number, @Val Claim claim, @Val ClaimActionRequest request,
            @Val PreviousDue previous,
            PersonRepository people,
            @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record(action.event() + " sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(number.value())
                + (action == ClaimAction.RESETTLE
                        ? " old=" + figure(previous.value()) + " new=" + figure(claim.due())
                        : action.settles() ? " due=" + figure(claim.due()) : "")
                + (action == ClaimAction.REJECT ? " reason=" + request.reason() : "")
                + (action == ClaimAction.VOID && previous.settled() ? " reversed=" + figure(previous.value()) : ""));
    }

    private static String figure(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.Locale;
import java.util.stream.Collectors;

/**
 * A claim a person has on a sheet. {@code id} is null until the claim is first saved; {@code number}
 * is null unless the claim has been opened (a draft has none; a voided claim keeps it). {@code due} is the
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a figure, {@code statedDue} (null: n/a) — it then shows and totals
 * that figure, not its live one. {@code number} is sheet-wide (1, 2, ...) or, under period numbering,
 * within its period (P1-1, X-1). {@code corrects} is, for a correction, the number of the claim it corrects (null:
 * not a correction). {@code dueBy} is fixed when the claim is created: the terms-th business day after its date (skipping Saturdays,
 * Sundays and the sheet's holidays) for its person's own terms, else those of their grade, else the sheet's, each in
 * force on that date; it does not change when the terms or its date change later. While PENDING the claim is not bound: it shows and totals its live figure, and is bound again
 * once rejected (back to OPEN) when the statement included it. {@code deferredUntil} is the date an OPEN claim is
 * deferred until (null: never deferred): while the sheet's today is before it the claim is {@link #deferred deferred}.
 * {@code proofs} is how many proofs the claim has been given. {@code splitFrom} is the number of the claim it was split
 * off (null: not split off another claim).
 */
public record Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
        String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, String splitFrom) {

    /** A claim not split off another claim. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, proofs, null);
    }

    /** A claim with no proofs. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, 0);
    }

    /** A claim never deferred. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, null);
    }

    /** The same claim with another status, number, fixed due and opener. */
    public Claim withStatus(ClaimStatus next, String nextNumber, BigDecimal nextDue, String nextOpenedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, next, nextNumber, nextDue, nextOpenedBy, stated,
                statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /** The same claim as an open claim bound by no statement: live, with no fixed due. */
    public Claim asOpenUnbound() {
        return new Claim(id, sheetId, personId, amount, date, note, ClaimStatus.OPEN, number, null, openedBy, false,
                null, corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /**
     * The claim keeping the rest of its amount once the split amount goes to a new claim: it loses any figure a
     * statement bound it to.
     */
    public Claim splitKeeping(BigDecimal rest) {
        return new Claim(id, sheetId, personId, rest, date, note, status, number, due, openedBy, false, null,
                corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /** Whether the claim is a correction: a negative amount naming the settled claim it corrects. */
    public boolean correction() {
        return corrects != null;
    }

    /** Whether the claim counts toward the totals: only OPEN, PENDING and SETTLED claims do. */
    public boolean counts() {
        return status.open() || status == ClaimStatus.SETTLED;
    }

    /** Whether the claim counts toward the live totals when a hold on its person covers it or not: a held open (or pending) claim does not. */
    public boolean counts(boolean held) {
        return status == ClaimStatus.SETTLED || (status.open() && !held);
    }

    /**
     * Whether the claim is deferred on the given today: OPEN, deferred until a date after that day. A deferred claim
     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
     */
    public boolean deferred(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /** The same claim deferred until the date. */
    public Claim deferTo(LocalDate until) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                corrects, dueBy, until, proofs, splitFrom);
    }

    /** The same claim on another date with the given number, keeping its due-by and any statement figure. */
    public Claim redateTo(LocalDate nextDate, String nextNumber) {
        return new Claim(id, sheetId, personId, amount, nextDate, note, status, nextNumber, due, openedBy, stated,
                statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /** The same claim with one more proof. */
    public Claim withProof() {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                corrects, dueBy, deferredUntil, proofs + 1, splitFrom);
    }

    /** Whether a proof can be added to the claim: it is neither SETTLED nor VOID. */
    public boolean takesProof() {
        return status != ClaimStatus.SETTLED && status != ClaimStatus.VOID;
    }

    /** Whether the claim is overdue on the given today: OPEN (or PENDING), not deferred, with its due-by before that day. */
    public boolean overdue(LocalDate today) {
        return overdue(today, 0);
    }

    /** Whether the claim is overdue on the given today with the grace days: its due-by plus them before that day. */
    public boolean overdue(LocalDate today, int grace) {
        return status.open() && !deferred(today) && dueBy != null && today != null
                && dueBy.plusDays(grace).isBefore(today);
    }

    /** Whether a statement binds the claim now: it was stated and is not PENDING. */
    public boolean bound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
    public boolean keepsFigure() {
        return due != null || (bound() && statedDue != null);
    }

    /**
     * The claim's figure (null: n/a): the due fixed when it was settled, else the figure its statement bound
     * it to (not while PENDING), else its amount at the given live rate (null: none) — no floor. Its live figure
     * rounds by the sheet's policy date.
     */
    public BigDecimal figure(BigDecimal liveRate, Rounding rounding) {
        if (due != null) {
            return due;
        }
        if (bound()) {
            return statedDue;
        }
        return due(amount, liveRate, rounding.modeFor(this));
    }

    /**
     * The claim's due (null: n/a): the due fixed when it was settled, else the greater of the floor in force on its
     * date and its {@link #figure figure} plus the late charge on that figure while it is overdue. A settled claim's
     * fixed due already has the charge and floor frozen in; a correction has no floor and no charge.
     */
    public BigDecimal due(BigDecimal liveRate, BigDecimal floor, LateCharge late, Rounding rounding) {
        BigDecimal figure = figure(liveRate, rounding);
        if (due != null || figure == null || correction()) {
            return figure;
        }
        return atLeast(figure.add(late.on(this, figure, rounding.modeFor(this))), floor);
    }

    /** An amount times a percent rate, divided by 100, rounded by the mode to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, RoundingMode mode) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, mode);
    }

    /** The value raised to the floor (null: no floor). */
    static BigDecimal atLeast(BigDecimal value, BigDecimal floor) {
        return floor == null || value.compareTo(floor) >= 0 ? value : floor.setScale(2);
    }

    /** The audit field for a claim's external reference, " ref=<reference>", or "" when it has none. */
    public static String auditRef(String ref) {
        return ref == null ? "" : " ref=" + ref;
    }

    /**
     * Tags as typed (comma separated) in their stored form: each trimmed and lower-cased, blanks and repeats dropped,
     * sorted and comma separated; null when there are none.
     */
    public static String tags(String typed) {
        if (typed == null) {
            return null;
        }
        String tags = Arrays.stream(typed.split(",")).map((t) -> t.strip().toLowerCase(Locale.ROOT))
                .filter((t) -> !t.isEmpty()).distinct().sorted().collect(Collectors.joining(","));
        return tags.isEmpty() ? null : tags;
    }

    /** The audit field for a claim's tags, " tags=<a,b>", or "" when it has none. */
    public static String auditTags(String tags) {
        return tags == null ? "" : " tags=" + tags;
    }

    /** The audit field for the claim's number, " number=<n>", or "" when it has none. */
    public static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }
}
